examples.setup:
private static let sources = [
    MonarchColumnMappingSource("Full Name", samples: ["Sam Lee", "Ana Ruiz"]),
    MonarchColumnMappingSource("E-mail", samples: ["sam@example.com", "ana@example.org"]),
    MonarchColumnMappingSource("Phone", samples: ["+44 20 7946 0000"]),
    MonarchColumnMappingSource("Organisation name", samples: ["Example Ltd"]),
    MonarchColumnMappingSource("Notes"),
]
private static let fields = [
    MonarchColumnMappingField(id: "name", label: "Name", isRequired: true),
    MonarchColumnMappingField(id: "email", label: "Email", isRequired: true, aliases: ["E-mail", "Mail"]),
    MonarchColumnMappingField(id: "phone", label: "Phone number", description: "International format, e.g. +44 20 7946 0000"),
    MonarchColumnMappingField(id: "company", label: "Company"),
]
@State private var mapping = MonarchColumnMapping.mapping(
    from: MonarchColumnMapping.suggest(Self.sources, fields: Self.fields)
)

@State private var mapping: [String: String] = ["Mail": "email", "E-mail": "email"]
@State private var showsIssues = false
private let fields = [
    MonarchColumnMappingField(id: "email", label: "Email", isRequired: true),
    MonarchColumnMappingField(id: "name", label: "Name", isRequired: true),
]

examples.code:
VStack {
    MonarchColumnMapping(
        [MonarchColumnMappingSource("Mail"), MonarchColumnMappingSource("E-mail")],
        mapping: $mapping,
        fields: fields,
        showsIssues: showsIssues
    )
    .frame(minHeight: 360)
    Button("Next") {
        let issues = MonarchColumnMapping.issues(mapping, fields: fields)
        showsIssues = !issues.missing.isEmpty || !issues.duplicates.isEmpty
    }
}
